import { STYLE_CONFIGS } from '../config/styles';
import { StyleKey } from '../types/env';

export interface GenerateResult {
  jobId: string;
  imageUrl: string;
  styleKey: StyleKey;
  petName: string;
  latencyMs: number;
  isFallback: boolean;
}

export type FalRunner = (
  prompt: string,
  imageBase64: string | undefined,
  apiKey: string,
  signal: AbortSignal
) => Promise<{ jobId: string; imageUrl: string }>;

/**
 * Default Fal.ai runner using standard fetch with Cloudflare Workers
 */
export const defaultFalRunner: FalRunner = async (prompt, imageBase64, apiKey, signal) => {
  const endpoint = 'https://fal.run/fal-ai/flux/schnell';
  
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Authorization': `Key ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      prompt,
      image_size: 'square_hd',
      num_images: 1,
      enable_safety_checker: true
    }),
    signal
  });

  if (!response.ok) {
    throw new Error(`Fal.ai upstream error: ${response.status} ${response.statusText}`);
  }

  const data = (await response.json()) as { images?: Array<{ url: string }>; request_id?: string };
  const imageUrl = data.images?.[0]?.url;
  if (!imageUrl) {
    throw new Error('No image returned from Fal.ai');
  }

  return {
    jobId: data.request_id || `fal_${crypto.randomUUID().slice(0, 8)}`,
    imageUrl
  };
};

export class FalService {
  private runner: FalRunner;
  private timeoutMs: number;

  constructor(runner: FalRunner = defaultFalRunner, timeoutMs: number = 5000) {
    this.runner = runner;
    this.timeoutMs = timeoutMs;
  }

  /**
   * Execute Haute Couture Pet Generation with 5000ms hard timeout and graceful degradation (NC-4)
   */
  async generatePoster(
    styleKey: StyleKey,
    petName: string,
    imageBase64: string | undefined,
    apiKey?: string
  ): Promise<GenerateResult> {
    const start = Date.now();
    const styleConfig = STYLE_CONFIGS[styleKey];
    const fallbackImage = styleConfig.fallbackImageUrl;

    // NC-2 & NC-6: If no API key is set, immediately degrade to fallback gracefully
    if (!apiKey) {
      return {
        jobId: `fallback_${crypto.randomUUID().slice(0, 8)}`,
        imageUrl: fallbackImage,
        styleKey,
        petName,
        latencyMs: Date.now() - start,
        isFallback: true
      };
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.timeoutMs);

    try {
      // NC-6: Prompt is strictly determined by style whitelist, petName is NOT injected
      const result = await this.runner(styleConfig.prompt, imageBase64, apiKey, controller.signal);
      clearTimeout(timeoutId);

      return {
        jobId: result.jobId,
        imageUrl: result.imageUrl,
        styleKey,
        petName,
        latencyMs: Date.now() - start,
        isFallback: false
      };
    } catch (err: unknown) {
      clearTimeout(timeoutId);
      const isTimeout = err instanceof Error && (err.name === 'AbortError' || err.message.includes('abort'));
      const latency = isTimeout ? this.timeoutMs : Date.now() - start;

      console.warn(
        `[FalService] Generation fallback triggered (${isTimeout ? 'TIMEOUT_5000MS' : 'UPSTREAM_ERROR'}):`,
        err instanceof Error ? err.message : String(err)
      );

      // NC-4: Graceful fallback to pristine haute couture photography
      return {
        jobId: `fallback_${crypto.randomUUID().slice(0, 8)}`,
        imageUrl: fallbackImage,
        styleKey,
        petName,
        latencyMs: latency,
        isFallback: true
      };
    }
  }
}

export const falService = new FalService();
